/**
 * Pure mapping between the brain protocol and this app's bus and screens.
 * (Brain integration layer — not generated by Lovable. See docs/integration.md §14.)
 */
import type { DownlinkPayload, RunPhase, StageView, ToolName } from "@coach/protocol";
import type { Feedback } from "../signals/bus";

export type ScreenPath = "/" | "/presenter" | "/judges" | "/report";

/** feedback.set → the bus "feedback" channel the Vignette reads. */
export function feedbackToBus(f: DownlinkPayload<"feedback.set">): Feedback {
  if (f.kind === "warn") return { color: "red", intensity: f.intensity };
  if (f.kind === "reward") return { color: "green", intensity: f.intensity };
  return { color: "neutral", intensity: 0 };
}

/** Which screen shows each brain view (setup uploads the deck on the presenter screen). */
export function viewToRoute(view: StageView): ScreenPath {
  switch (view) {
    case "setup": return "/presenter";
    case "jj": return "/";
    case "slides": return "/presenter";
    case "room": return "/judges";
    case "report": return "/report";
    case "final": return "/report";
  }
}

export type Intent =
  | { kind: "tool"; tool: ToolName; args: Record<string, unknown>; label: string }
  | { kind: "send"; type: "presentation.done"; label: string }
  | { kind: "hint"; text: string };

/**
 * The brain decides the view. When the user navigates away from it (Next buttons, keys
 * 1-4), translate the move into the loop action it means; anything else snaps back.
 */
export function intentFor(view: StageView, runPhase: RunPhase | null, to: ScreenPath): Intent {
  if (view === "setup") return { kind: "hint", text: "Upload your deck (PDF) first" };
  if ((view === "jj" || view === "report" || view === "final") && to === "/presenter") {
    return { kind: "tool", tool: "start_run", args: {}, label: "Starting the run" };
  }
  if (view === "slides" && runPhase === "presentation" && to === "/judges") return { kind: "send", type: "presentation.done", label: "Slides done" };
  if (view === "room" && to === "/report") return { kind: "tool", tool: "end_run", args: {}, label: "Ending the run" };
  if (view === "report" || view === "final") return { kind: "hint", text: "Tell JJ when you're ready, or press Start run" };
  return { kind: "hint", text: "JJ is running the session" };
}

/** Orb level: JJ's voice while speaking, the mic (softer) while listening, a calm idle otherwise. */
export function orbTarget(jj: { speaking: boolean; listening: boolean } | null, jjLevel: number, micLevel: number): number {
  if (jj?.speaking) return Math.min(1, 0.35 + jjLevel * 2.5);
  if (jj?.listening) return Math.min(1, 0.2 + micLevel * 1.5);
  return 0.15;
}

/** Whether the stage should report a slide change to the brain. */
export function reportsSlides(runPhase: RunPhase | null | undefined): boolean {
  return runPhase === "presentation" || runPhase === "countdown";
}
